return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'mr','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'या साइटची मीडिया लायब्ररी Zinn® ऑब्जेक्ट स्टोरेजवर हलवते आणि ती CDN वरून सर्व्ह करते. तुमच्या Zinn® डॅशबोर्डवरून कॉन्फिगर केले जाते — WordPress मध्ये कोणतीही ऍक्सेस की कधीही टाइप केली जात नाही.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'संग्रह केला आहे. ती बदलण्यासाठी एक नवीन मूल्य टाइप करा.','Filter this list…'=>'ही यादी फिल्टर करा...','Filter this list'=>'या सूचीला फिल्टर करा','Nothing matches that filter.'=>'त्या फिल्टरशी जुळणारे काहीही नाही.','Add a row'=>'ओळ जोडा','Remove this row'=>'ही ओळ काढा','Remove'=>'काढून टाका','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — अवलोकन','Overview'=>'आढावा','Every Zinn® plugin on this site, and whether it is working.'=>'या साइटवरील प्रत्येक Zinn® प्लगइन आणि ते कार्य करत आहे की नाही.','No connection is needed for this plugin.'=>'या प्लगइनसाठी कोणत्याही कनेक्शनची आवश्यकता नाही.','Open settings'=>'सेटिंग्ज उघडा','You do not have permission to change these settings.'=>'तुम्हाला हे सेटिंग्ज बदलण्याची परवानगी नाही.','Settings sections'=>'सेटिंग्स विभाग','Support'=>'सपोर्ट','Save changes'=>'बदल जतन करा','Tools'=>'टूलबाक्सेस','Export settings'=>'निर्यात सेटिंग्ज','Reset to defaults'=>'डीफॉल्टवर रीसेट करा','This puts every setting on this plugin back to its default. Continue?'=>'यामुळे या प्लगइनवरील प्रत्येक सेटिंग पूर्वस्थितीत परत येईल. सुरू ठेवायचे का?','Diagnostics for support'=>'सपोर्टसाठी डायग्नोस्टिक्स','Import a settings file'=>'सेटिंग्स फाईल इम्पोर्ट करा','Import'=>'आयात करा','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'निर्यात केलेल्या फाईल्समध्ये कधीही पासवर्ड, टोकन्स किंवा API की नसतात — नवीन साइटवर तुम्हाला त्या पुन्हा प्रविष्ट कराव्या लागतील.','Settings saved.'=>'सेटिंग्स जतन केल्या.','Every setting on this plugin is back to its default.'=>'या प्लगइनवरील प्रत्येक सेटिंग पूर्वस्थितीत आली आहे.','Done.'=>'पूर्ण झाले.','That action is not available.'=>'ती कृती उपलब्ध नाही.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'ती फाइल वाचता आली नाही. Zinn® प्लगइनमधून निर्यात केलेली सेटिंग्ज फाइल निवडा.','That file is too large to be a settings export.'=>'ती फाइल सेटिंग्स निर्यात करण्यासाठी खूप मोठी आहे.','That file is not a Zinn® settings export.'=>'ती फाईल Zinn® सेटिंग्ज निर्यात नाही.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'ती फाइल एका वेगळ्या प्लगइनमधून (%s) एक्सपोर्ट केली गेली होती, त्यामुळे ती इथे इम्पोर्ट केल्यास हे प्लगइन समजू शकत नाही अशा सेटिंग्ज सेव्ह केल्या जातील.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d सेटिंग आयात केली. पासवर्ड आणि API की कधीही एक्स्पोर्टमध्ये नसतात, त्यामुळे त्या पुन्हा प्रविष्ट करा.' . "\0" . '%d सेटिंग्ज इम्पोर्ट केल्या आहेत. पासवर्ड आणि API की कधीही एक्सपोर्टमध्ये समाविष्ट केल्या जात नाहीत, त्यामुळे त्या पुन्हा प्रविष्ट करा.','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® ने टोकन परत केले नाही. या साइटवर काहीही बदलले गेलेले नाही.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'هي साइट आता Zinn® मीडिया ऑफलोडशी कनेक्ट केलेली नाही. नवीन अपलोड या सर्व्हरवरच राहतील. ते तुमच्या Zinn Digital® डॅशबोर्डवरून पुन्हा पेअर करा.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® ने HTTP %d सह उत्तर दिले.','Disconnected by Zinn Digital®.'=>'Zinn Digital® द्वारे डिस्कनेक्ट केले.','Connected'=>'कनेक्ट केलेले','Connecting…'=>'जोडत आहे…','Connected, but something needs attention'=>'कनेक्ट केलेले आहे, पण काहीतरी लक्ष वेधून घेत आहे','Not connected'=>'जोडलेले नाही','Running on your own account'=>'तुमच्या स्वतःच्या खात्यावर चालत आहे','We could not check this'=>'आम्ही हे तपासू शकलो नाही','This plugin did not say why. Send a diagnostics report and we will look.'=>'या प्लगइनने याचे कारण सांगितलेले नाही. डायग्नोस्टिक्स अहवाल पाठवा आणि आम्ही तपास करू.','Connection status'=>'कनेक्शन स्थिती','Last checked %s ago.'=>'शेवटची तपासणी %s पूर्वी केली.','(opens in a new tab)'=>'(नवीन टॅबमध्ये उघडते)','Send this to Zinn® support'=>'Zinn® सपोर्टला हे पाठवा','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'हे नेमके पाठवले जाईल — दुसरे काहीही नाही आणि काहीही लपवलेले नाही. तुमचे पासवर्ड, टोकन्स आणि API की यामध्ये नाहीत.','The diagnostics report that will be sent'=>'पाठवले जाणारे डायग्नोस्टिक्स अहवाल','Copy to clipboard'=>'क्लिपबोर्डवर कॉपी करा','Send this report to Zinn® support'=>'हा अहवाल Zinn® समर्थनाला पाठवा','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'आम्ही तुमच्यासाठी सपोर्ट तिकीट उघडतो आणि ईमेलद्वारे उत्तर देतो. तुम्हाला ते पाठवायचे नसेल, तर ते वरून कॉपी करा आणि स्वतः तिकीटमध्ये पेस्ट करा.','Copied'=>'कॉपी केले','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'आम्हाला या सर्व्हरवरून Zinn Digital® पर्यंत पोहोचता आले नाही (%s). वरील अहवाल कॉपी करा आणि त्याऐवजी एक तिकीट उघडा — तुमच्या सेटिंग्जमध्ये काहीही चुकीचे नाही.','Sent. Zinn® support has your report and will reply by email.'=>'पाठवले आहे. Zinn® सपोर्टकडे तुमचा अहवाल प्राप्त झाला आहे आणि ते ईमेलद्वारे उत्तर देतील.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'पाठवले. Zinn® सपोर्टकडे तुमचा अहवाल प्राप्त झाला आहे - संदर्भ %s - आणि ते ईमेलद्वारे उत्तर देतील.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'तुम्ही कमी वेळात अनेक अहवाल पाठवले आहेत. काही मिनिटे थांबा आणि पुन्हा प्रयत्न करा — आधीचे अहवाल मिळाले आहेत.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® या वेळी अहवाल स्वीकारू शकले नाही — ती आमची बाजू आहे, तुमची नाही. थोड्यावेळाने पुन्हा प्रयत्न करा किंवा वरील अहवाल तिकीटमध्ये कॉपी करा.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'अहवाल नाकारला गेला (HTTP %d). तो वर कॉपी करा आणि तो क्रमांक नमूद करून तिकीट उघडा.','%s — guides and services'=>'%s — मार्गदर्शक आणि सेवा','User guides'=>'वापरकर्ता मार्गदर्शक','Read the %s user guide'=>'%s वापरकर्ता मार्गदर्शक वाचा','Hide this'=>'हे लपवा','Zinn® hosting for WordPress'=>'WordPress साठी Zinn® होस्टिंग','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक बॅकअप, विनामूल्य स्थलांतर आणि एकापेक्षा जास्त साइट्स चालवणाऱ्या लोकांसाठी तयार केलेले कंट्रोल पॅनेल.','The Zinn® marketplace'=>'Zinn® मार्केटप्लेस','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'स्थापित साइट्स, डोमेन आणि लिंक प्लेसमेंट्सची खरेदी आणि विक्री करा, दोन्ही बाजू समाधानी होईपर्यंत पैसे सुरक्षित ठेवले जातात.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — हेच काम व्यावसायिक म्हणून करणाऱ्या लोकांची नियुक्ती करा','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'आमचे जागतिक फ्रीलान्स मार्केटप्लेस: लेखक, डिझायनर, डेव्हलपर आणि एसईओ (SEOs) कडील १०,००० हून अधिक तयार सेवा ब्राउझ करा किंवा एखादा प्रकल्प पोस्ट करा आणि त्यांना बोली लावू द्या.','Media Offload'=>'मीडिया ऑफलोड','Connection'=>'कनेक्शन','What gets moved'=>'काय स्थानांतरीत केले जाते','How media is served'=>'मीडिया कसा वितरीत केला जातो','Move a batch now'=>'आता एक बॅच हलवा','Media already moved is never affected by a change here — its address does not change.'=>'येथे केलेल्या बदलामुळे आधीच हलवलेल्या मीडियाचा कोणताही परिणाम होत नाही — त्याचा पत्ता बदलत नाही.','New uploads'=>'नवीन अपलोड्स','Move new uploads to Zinn® storage as they arrive'=>'नवीन अपलोड्स आल्यावर ते Zinn® स्टोरेजमध्ये हलवा','Existing media'=>'विद्यमान मीडिया','Keep moving the media library that is already here'=>'येथे आधीच असलेली मीडिया लायब्ररी हलवत राहणे चालू ठेवा','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'दर तासाला काही फाइल्स, पार्श्वभूमीवर, जिथून थांबले होते तिथून पुढे सुरू होतात. हे बंद केल्याने ते विसाव्यावर जाते; आधी हलवलेले काहीही परत येत नाही.','Files per hourly pass'=>'प्रत्येक तासाच्या पासमधील फाईल्स','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'प्रत्येक संलग्नक अनेक फाईल्स आहेत आणि त्यातील प्रत्येक एक पूर्ण अपलोड आहे. उदारमय अंमलबजावणी मर्यादा असलेल्या वेगवान होस्टवर हे वाढवा; जर पास अपूर्ण सोडले जात असतील तर ते कमी करा.','Leave files smaller than'=>'यापेक्षा लहान फायली ठेवा','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'किलोबाइट. डिस्कवर वाचवणाऱ्या पैशापेक्षा एका छोट्या आयकॉनच्या अतिरिक्त कनेक्शनसाठी जास्त खर्च येतो, त्यामुळे तो हलवण्याचे क्वचितच कारण असते. सर्वकाही हलवण्यासाठी 0 वर सेट करा.','Never move these types'=>'हे प्रकार कधीही हलवू नका','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'जेव्हा एखादी प्लगइन थेट डिस्कवरून फाईल वाचते तेव्हा उपयुक्त — एखादा फॉन्ट, फॉर्म बिल्डरने तयार केलेली पीडीएफ, किंवा प्लेअर ज्यामध्ये शोधू शकतो अशी ऑडिओ फाईल.','These two are the ones to be careful with — read each description before changing it.'=>'या दोघांची काळजी घेणे आवश्यक आहे — बदल करण्यापूर्वी प्रत्येक वर्णनाचे नीट वाचन करा.','Serve from Zinn® storage'=>'Zinn® स्टोरेजवरून सर्व्ह करा','Point image and file addresses at Zinn® storage'=>'Zinn® स्टोरेजकडे इमेज आणि फायलींच्या पत्ते निर्देशित करा','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'बंद आहे, फाइल्स अपलोड केल्या गेल्या आहेत पण तरीही या सर्व्हरवरून सर्व्ह केल्या जात आहेत — प्रत्येक गोष्ट व्यवस्थित पोहोचली आहे का याची खात्री करताना ही सुरक्षित स्थिती असते. सुरू आहे, अभ्यागतांना स्टोरेजवरून सर्व्ह केले जाते आणि हा सर्व्हर रहदारी वाहून नेणे थांबवतो.','Free the disk space'=>'डिस्क जागा मोकळी करा','Delete the local copy once every size has uploaded'=>'प्रत्येक साईझ अपलोड झाल्यावर स्थानिक प्रत हटवा','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'हा ऑफलोडिंगचा बिंदू आहे आणि हा अपरिवर्तनीय अर्धा भाग देखील आहे. “Serve from Zinn® storage” चालू होईपर्यंत आणि तुम्ही तुमच्या साइटची खात्री करेपर्यंत ते बंद ठेवा — काही सुटल्यास केवळ स्थानिक प्रतच तुम्हाला वाचवू शकते.','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'स्थानिक प्रती हटवणे या स्क्रीनवरून पूर्ववत करता येत नाही. आधी बॅकअप घ्या — Zinn® कनेक्टर प्लगइन तुमच्यासाठी ते करू शकते.','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'हे साइट अजून Zinn® स्टोरेजशी जोडलेले नाही, त्यामुळे मीडिया हलवण्यासाठी कोणतीही जागा नाही.','%d attachment moved.'=>'%d संलग्नक हलवले.' . "\0" . '%d संलग्नके हलवली.','This site is not connected to Zinn® storage.'=>'हे साइट Zinn® स्टोरेजशी जोडलेली नाही.','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'काहीही चुकीचे नाही — ते फक्त अद्याप जोडलेले नाही. जोपर्यंत ते जोडले जात नाही तोपर्यंत मीडिया या सर्व्हरवर राहील.','Connected, but the last upload failed.'=>'कनेक्ट केलेले आहे, पण मागील अपलोड अयशस्वी झाले.','Try a batch now'=>'आता एक बॅच वापरून पहा','Connected. Every attachment has been moved.'=>'जोडलेले आहे. प्रत्येक संलग्नक हलवले आहे.','Connected. %1$s of %2$s attachments still on this server.'=>'जोडलेले आहे. %1$s पैकी %2$s संलग्नके अद्याप या सर्व्हरवर आहेत.','Moved so far'=>'आतापर्यंत हलवले','%1$s files, %2$s'=>'%1$s फाइल्स, %2$s','Still on this server'=>'याच सर्व्हरवर अद्यापही','%1$s of %2$s attachments'=>'%2$s पैकी %1$s संलग्नके (अटॅचमेंट्स)','Served from'=>'येथून सर्व्ह केले जात आहे','this server'=>'हा सर्व्हर','Connect this site'=>'हे साइट कनेक्ट करा','Open your Zinn Digital® dashboard, go to Storage → Media offload, and press “Pair a site”. Paste the code below.'=>'तुमचे Zinn Digital® डॅशबोर्ड उघडा, Storage → Media offload वर जा, आणि “Pair a site” दाबा. खालील कोड पेस्ट करा.','Pairing code'=>'जोडणी कोड','Disconnect this site'=>'हे साइट डिस्कनेक्ट करा','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'नवीन अपलोड्स या सर्व्हरवरच राहतील. आधीच हलवलेले मीडिया काम करत राहील — त्याचा पत्ता बदलत नाही.','You do not have permission to manage this site.'=>'तुम्हाला हे साइट व्यवस्थापित करण्याची परवानगी नाही.','Paste the pairing code from your Zinn Digital® dashboard.'=>'तुमच्या Zinn Digital® डॅशबोर्डवरील पेअरिंग कोड पेस्ट करा.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'जोडलेले आहे. आतापासून नवीन अपलोड Zinn Digital® वर साठवले जातील आणि तुमचे विद्यमान मीडिया बॅकग्राउंडमध्ये हलवले जातील.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'डिसकनेक्ट केलेले आहे. आधीपासून हलवलेले मीडिया काम करत राहील; नवीन अपलोड याच सर्व्हरवर राहतील.','That file could not be read from this server, so nothing was uploaded.'=>'ती फाइल या सर्व्हरवरून वाचता आली नाही, त्यामुळे काहीही अपलोड केले गेले नाही.','This site could not stream the upload, so nothing was sent.'=>'हे साइट अपलोड स्ट्रीम करू शकली नाही, त्यामुळे काहीही पाठवले गेले नाही.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'ही फाईल %1$s आहे आणि या साइटच्या PHP मध्ये cURL नाही, त्यामुळे ही जास्तीत जास्त %2$s अपलोड करू शकते.','The upload could not be completed.'=>'अपलोड पूर्ण होऊ शकले नाही.','Storage refused the upload (HTTP %d).'=>'स्टोरेजने अपलोड नाकारले (HTTP %d).','Style preset'=>'शैली प्रीसेट','A starting point. Anything below overrides it.'=>'एक सुरुवातीचा बिंदू. याच्या खालील कोणतेही साधन त्यावरील मर्यादा ओव्हरराइड करते.','Use my own colours and sizes'=>'माझे स्वतःचे रंग आणि आकार वापरा','Leave this off and the preset is used exactly as it is.'=>'हे बंद ठेवा आणि प्रीसेट जसेच्या तसे वापरले जाते.','See the Zinn Digital® release notes.'=>'Zinn Digital® च्या रिलीझ नोट्स पहा.','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड केलेल्या अपडेटची अखंडता चाचणी (इंटीग्रिटी चेक) अयशस्वी झाली आणि ते इन्स्टॉल केले गेले नाही.']];